const show=()=>{const d=+queryDay.value,h=+queryHours.value,old=d<8||!evolve.checked,spec=old?'day(event_time)':'hour(event_time)',files=old?1:h,scanned=old?24:h;world.textContent='Logical predicate: event_time on Day '+d+' for '+h+' hour(s)
File partition spec used: '+spec+'
Files selected in toy table: '+files+'
Time represented by selected files: '+scanned+' hour(s)
Historical files rewritten by spec change: 0

'+(old&&evolve.checked?'Old layout remains valid; pruning is coarser.':old?'No evolution: all writes stay daily.':'New layout: the same source-column filter derives hourly pruning.')};[queryDay,queryHours,evolve].forEach(e=>e.oninput=show);show();
function drawMechanism(){const d=+queryDay.value,h=+queryHours.value,daily=d<8||!evolve.checked;mechanism.innerHTML='<p>Selected Day '+d+' · '+(daily?'daily file':'hourly files')+'. The query starts at hour 0 in this toy.</p><p><strong>Logical query: hours 0–'+(h-1)+'</strong></p><div style="display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:3px">'+Array.from({length:24},(_,i)=>'<div style="border:'+(i<h?'2px solid #ffdf96':'1px dashed #72969c')+';padding:5px 0;text-align:center;font-size:.85rem">'+i+(i<h?'✓':'')+'</div>').join('')+'</div><p>↓ Planner selects intersecting files</p>'+(daily?'<div class="mv-box"><strong>One file spans hours 0–23</strong><p>The requested hours are inside this file. Select the whole file; row filtering still keeps only matching events.</p></div>':'<div class="mv-row">'+Array.from({length:h},(_,i)=>'<span class="mv-chip">file h'+i+' ✓</span>').join('')+'</div><p>Other hourly files are skipped.</p>')+'<p class="mv-note">Selected file coverage: '+(daily?24:h)+' hours for '+h+' requested. '+(d<8&&evolve.checked?'Changing new writes does not split this historical daily file.':'The logical event-time filter keeps the same meaning.')+'</p>'; }
[queryDay,queryHours,evolve].forEach(el=>{for(const event of ['onclick','oninput']){const original=el[event];if(original)el[event]=function(...args){const result=original.apply(this,args);drawMechanism();return result}}});drawMechanism();

const nodes=[['A',0],['B',21],['C',42],['D',10],['E',31]],hash=i=>(i*37+13)%64;const owner=(h,n,kind)=>{if(kind==='mod')return nodes[h%n][0];return nodes.slice(0,n).sort((a,b)=>a[1]-b[1]).find(x=>x[1]>=h)?.[0]||nodes.slice(0,n).sort((a,b)=>a[1]-b[1])[0][0]};const show=()=>{const n=+nodeCount.value,k=mapping.value,base=Array.from({length:60},(_,i)=>owner(hash(i),3,k)),now=Array.from({length:60},(_,i)=>owner(hash(i),n,k)),moved=now.filter((x,i)=>x!==base[i]).length,counts=nodes.slice(0,n).map(x=>x[0]+': '+now.filter(v=>v===x[0]).length).join(' | ');world.textContent='Strategy: '+(k==='ring'?'fixed ring, first node clockwise':'hash modulo active node count')+'
Active: '+nodes.slice(0,n).map(x=>x[0]).join(', ')+'
Keys per owner: '+counts+'
Keys moved versus three-node baseline: '+moved+'/60

'+(n===3?'Add a node to observe remapping.':k==='ring'?'Only newly claimed ring arcs move in this model.':'Changing the divisor remaps keys across the fleet.')};[mapping,nodeCount].forEach(e=>e.oninput=show);show();
function drawMechanism(){const n=+nodeCount.value,k=mapping.value,active=nodes.slice(0,n).sort((a,b)=>a[1]-b[1]);let pic='';if(k==='ring'){const point=h=>[170+110*Math.sin(h/64*2*Math.PI),150-110*Math.cos(h/64*2*Math.PI)];pic='<svg viewBox="0 0 340 315" role="img" aria-label="64-slot clockwise ring with nodes at fixed positions"><circle cx="170" cy="150" r="110" fill="none" stroke="#8dacad" stroke-width="2"/><text x="170" y="142" text-anchor="middle" font-size="17">64-slot ring</text><text x="170" y="166" text-anchor="middle" font-size="15">clockwise →</text>';for(const [name,h] of active){const [x,y]=point(h);pic+='<circle cx="'+x+'" cy="'+y+'" r="17" fill="#315965" stroke="#f5d994"/><text x="'+x+'" y="'+(y+5)+'" text-anchor="middle" font-size="17">'+name+'</text><text x="'+x+'" y="'+(y+35)+'" text-anchor="middle" font-size="14">slot '+h+'</text>';}pic+='</svg><p>Choose the first node at or after the key hash clockwise; wrap after slot 63.</p>';}else pic='<p>Modulo routing: hash % '+n+' selects an index in ['+nodes.slice(0,n).map(x=>x[0]).join(', ')+']. Changing the divisor can change every old mapping.</p>';const samples=[2,7,13,25,37,50];mechanism.innerHTML=pic+'<table><thead><tr><th>Key hash</th><th>3 nodes</th><th>'+n+' nodes</th><th>Movement</th></tr></thead><tbody>'+samples.map(h=>{const before=owner(h,3,k),after=owner(h,n,k);return '<tr><td>'+h+'</td><td>'+before+'</td><td>'+after+'</td><td>'+(before===after?'stays':before+' → '+after)+'</td></tr>'}).join('')+'</tbody></table><p class="mv-note">'+(k==='ring'?'D at 10 takes hashes (0,10] from B; E at 31 takes (21,31] from C. A hash of 50 wraps to A.':'Compare the same sampled hashes: this is remapping caused by a changed divisor, not a new ring arc.')+' Sample rows illustrate ownership; the total below counts all 60 synthetic keys.</p>'; }
[mapping,nodeCount].forEach(el=>{for(const event of ['onclick','oninput']){const original=el[event];if(original)el[event]=function(...args){const result=original.apply(this,args);drawMechanism();return result}}});drawMechanism();

const show=()=>{const criticalRate=4,criticalLatency=.2,bulkRate=6,bulkSec=+bulkLatency.value/1000,needCritical=criticalRate*criticalLatency,needBulk=bulkRate*bulkSec;let criticalServed,bulkServed;if(isolated.checked){criticalServed=Math.min(criticalRate,4/criticalLatency);bulkServed=Math.min(bulkRate,6/bulkSec)}else{const demand=needCritical+needBulk,share=Math.min(1,10/demand);criticalServed=criticalRate*share;bulkServed=bulkRate*share}world.textContent='Estimated in-flight demand
  critical: '+needCritical.toFixed(1)+' slots
  bulk: '+needBulk.toFixed(1)+' slots
Pool design: '+(isolated.checked?'critical 4 | bulk 6':'shared 10')+'
Estimated admitted throughput
  critical: '+criticalServed.toFixed(1)+'/s of 4.0/s
  bulk: '+bulkServed.toFixed(1)+'/s of 6.0/s
Outcome: '+(criticalServed>=4?'critical path protected in this model':'critical path loses capacity to the slow mode')};[bulkLatency,isolated].forEach(e=>e.oninput=show);show();
function drawMechanism(){const bulk=6*(+bulkLatency.value/1000),critical=.8,share=Math.min(1,10/(bulk+critical)),c=isolated.checked?critical:critical*share,b=isolated.checked?Math.min(6,bulk):bulk*share;const pool=(name,used,cap,other=0)=>'<div class="mv-box"><strong>'+name+' · '+cap+' slots</strong><div class="mv-bar" style="display:flex;height:32px"><span style="width:'+(used/cap*100)+'%;background:#5b96a0"></span>'+(other?'<span style="width:'+(other/cap*100)+'%;background:#9f8957"></span>':'')+'</div><p>'+used.toFixed(2)+' policy slots'+(other?' + '+other.toFixed(2)+' enrichment slots':'')+'</p></div>';mechanism.innerHTML='<p>Demand = arrival rate × time in service. Policy: 4/s × 0.2s = 0.8 slots. Enrichment: 6/s × '+(+bulkLatency.value/1000).toFixed(1)+'s = '+bulk.toFixed(1)+' slots.</p>'+(isolated.checked?'<div class="mv-grid">'+pool('Policy reserved',c,4)+'<div class="mv-box"><strong>Enrichment reserved · 6 slots</strong><div class="mv-bar"><span style="width:'+(b/6*100)+'%;background:#9f8957"></span></div><p>'+b.toFixed(2)+' used; '+Math.max(0,bulk-6).toFixed(1)+' requested slots not admitted.</p></div></div>':pool('One shared pool',c,10,b))+'<p>↓ Resulting policy throughput: <strong>'+((c/.2).toFixed(2))+'/s of 4/s</strong></p><p class="mv-note">'+(isolated.checked?'The divider reserves policy capacity. Empty policy slots cannot be borrowed by enrichment in this model.':'With excess combined demand, this toy scales both classes down proportionally. It does not model FIFO queues or priority scheduling.')+'</p>'; }
[bulkLatency,isolated].forEach(el=>{for(const event of ['onclick','oninput']){const original=el[event];if(original)el[event]=function(...args){const result=original.apply(this,args);drawMechanism();return result}}});drawMechanism();

const items={goal:1000,decisions:2000,openTasks:1500,pointers:1000,recentConversation:3000,rawToolOutput:8000};const orders={tail:['rawToolOutput','recentConversation','openTasks','decisions','pointers','goal'],structured:['goal','decisions','openTasks','pointers','recentConversation','rawToolOutput']};const show=()=>{let left=+contextBudget.value,kept=[];for(const k of orders[contextPolicy.value])if(items[k]<=left){kept.push(k);left-=items[k]}const required=['goal','decisions','openTasks','pointers'],missing=required.filter(x=>!kept.includes(x));world.textContent='Budget: '+contextBudget.value+' tokens
Policy: '+contextPolicy.options[contextPolicy.selectedIndex].text+'
Kept: '+(kept.join(', ')||'(none)')+'
Unused budget: '+left+'
Critical continuation fields missing: '+(missing.join(', ')||'none in this toy policy')+'

Durable source trace remains outside this working context.'};[contextBudget,contextPolicy].forEach(e=>e.oninput=show);show();
function drawMechanism(){let left=+contextBudget.value,kept=[];const order=orders[contextPolicy.value];const rows=order.map(k=>{const fits=items[k]<=left;if(fits){left-=items[k];kept.push(k)}return '<tr><td>'+k+'</td><td>'+items[k]+'</td><td>'+(fits?'✓ keep':'✕ skip')+'</td><td>'+left+'</td></tr>'}).join('');const req=['goal','decisions','openTasks','pointers'];mechanism.innerHTML='<p>Pack segments in the displayed order. A segment enters only if it fits completely.</p><table><thead><tr><th>Next segment</th><th>Tokens</th><th>Decision</th><th>Tokens left</th></tr></thead><tbody>'+rows+'</tbody></table><p>↓ Handoff readiness</p><div class="mv-row">'+req.map(k=>'<span class="mv-chip">'+(kept.includes(k)?'✓':'✕')+' '+k+'</span>').join('')+'</div><p class="mv-note">'+(kept.includes('decisions')?'The rule “preserve old partition readers” can remain in the decisions segment.':'The decisions segment is missing: the next agent may no longer have “preserve old partition readers”.')+' Full evidence remains stored outside this working context.</p>'; }
[contextBudget,contextPolicy].forEach(el=>{for(const event of ['onclick','oninput']){const original=el[event];if(original)el[event]=function(...args){const result=original.apply(this,args);drawMechanism();return result}}});drawMechanism();

const show=()=>{world.textContent='Set the trust and capability gates, then trace the request.'};trace.onclick=()=>{const steps=['1. Untrusted image reached the model'];if(!visualFollow.checked){steps.push('2. Model did not follow the embedded instruction — path stops');world.textContent=steps.join('
');return}steps.push('2. Model follows embedded instruction');if(!parseableCall.checked){steps.push('3. Tool output is invalid — parser rejects it');world.textContent=steps.join('
');return}steps.push('3. Tool call parses');if(capability.value!=='write'){steps.push('4. Capability boundary denies file write — path stops');world.textContent=steps.join('
');return}steps.push('4. Broad file-write capability authorizes action');if(!policyMutable.checked){steps.push('5. Protected policy path rejects mutation — path stops');world.textContent=steps.join('
');return}steps.push('5. Policy/config mutation succeeds in this toy path','RESULT: untrusted pixels reached a durable control surface');world.textContent=steps.join('
')};[visualFollow,parseableCall,capability,policyMutable].forEach(e=>e.oninput=show);show();
function drawMechanism(){const ran=world.textContent.startsWith('1.'),gates=[['Image reaches model',true],['Model follows instruction',visualFollow.checked],['Tool proposal parses',parseableCall.checked],['Capability permits write',capability.value==='write'],['Policy path is writable',policyMutable.checked]];let alive=true;mechanism.innerHTML='<p>'+(ran?'Executed Boolean path:':'Preview; press Trace request to execute:')+'</p><ol style="padding-left:25px">'+gates.map(([label,pass],i)=>{const reached=alive,status=!reached?'NOT REACHED':pass?'PASS':'STOP';alive=alive&&pass;return '<li style="padding:9px;border-left:3px '+(!reached?'dashed':'solid')+' #aac4c5;margin:4px 0"><strong>'+label+'</strong><br>'+status+(!reached?' — an earlier gate blocked the path':!pass?' — no later gate runs':' → continue')+'</li>'}).join('')+'</ol><div class="mv-box"><strong>Durable policy state: '+(alive?'MUTATED in this toy':'UNCHANGED')+'</strong><p>'+(alive?'Every gate allowed the path. A parseable proposal carried untrusted image instructions into a durable change.':'The first STOP blocks this path. Other inputs and actions still need their own checks.')+'</p></div>'; }
[visualFollow,parseableCall,capability,policyMutable,trace].forEach(el=>{for(const event of ['onclick','oninput']){const original=el[event];if(original)el[event]=function(...args){const result=original.apply(this,args);drawMechanism();return result}}});drawMechanism();
